import { Mesh, PlaneGeometry, Object3D, Vector2 } from 'three/webgpu';
import { MeshBasicNodeMaterial, texture, uv, uvTransform } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {Object} assets
 * @property {string} assets.imageUrl
 * @property {Array<number>} position
 * @property {Array<number>} rotation
 * @property {Array<number>} scale
 * @property {Object} atlasRegion
 * @property {Object} atlasRegion.sourceRect
 * @property {number} atlasRegion.sourceRect.x
 * @property {number} atlasRegion.sourceRect.y
 * @property {number} atlasRegion.sourceRect.width
 * @property {number} atlasRegion.sourceRect.height
 */

/**
 * @typedef {Object} NodeContext
 * @property {function(string): import('three').Texture} textureLoader
 * @property {Object<string, function(Object3D, any): void>} primitives
 */

/**
 * Creates a billboarded textured plane for the hero showpiece.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
	// ---- Load texture -------------------------------------------------
	const imageUrl = config?.assets?.imageUrl;
	const tex = imageUrl ? ctx.textureLoader(imageUrl) : null;

	// ---- Determine atlas UV region ------------------------------------
	const defaultRect = { x: 0, y: 0, width: 512, height: 320 };
	const rect = (config?.atlasRegion?.sourceRect) || defaultRect;

	// Fallback UV values if texture is not yet available
	const texWidth = (tex && tex.source?.data?.width) || (tex && tex.image?.width) || rect.width;
	const texHeight = (tex && tex.source?.data?.height) || (tex && tex.image?.height) || rect.height;

	const uvScale = new Vector2(rect.width / texWidth, rect.height / texHeight);
	const uvOffset = new Vector2(rect.x / texWidth, rect.y / texHeight);

	// ---- Build node material -------------------------------------------
	const uvNode = uv();
	const uvTransformed = uvTransform(uvNode, uvOffset, uvScale);
	const mapNode = texture(tex, uvTransformed);

	const material = new MeshBasicNodeMaterial({
		map: mapNode,
		transparent: true,
		depthWrite: false,
	});

	// ---- Geometry (aspect based on atlas region) -----------------------
	const aspect = rect.width / rect.height;
	const geometry = new PlaneGeometry(aspect, 1, 1, 1);

	// ---- Mesh -----------------------------------------------------------
	const mesh = new Mesh(geometry, material);
	mesh.frustumCulled = false; // ensure always rendered as UI

	// Apply placement
	if (config?.position?.length === 3) {
		mesh.position.set(config.position[0], config.position[1], config.position[2]);
	}
	if (config?.rotation?.length === 3) {
		mesh.rotation.set(config.rotation[0], config.rotation[1], config.rotation[2]);
	}
	if (config?.scale?.length === 3) {
		mesh.scale.set(config.scale[0], config.scale[1], config.scale[2]);
	}

	// ---- Billboard behavior ---------------------------------------------
	mesh.onBeforeRender = function (_renderer, _scene, camera) {
		mesh.quaternion.copy(camera.quaternion);
	};

	// ---- User data (handlers & cleanup) ---------------------------------
	mesh.userData.handlers = {};

	mesh.userData.cleanup = function () {
		// Remove billboard callback
		mesh.onBeforeRender = null;

		// Dispose resources owned by this node
		geometry.dispose();
		material.dispose();

		// Note: texture is managed by the context cache; do not dispose it here.
	};

	return mesh;
}
